#pragma once
#include <juce_audio_formats/juce_audio_formats.h>
#include <regex>
#include "MobilePrivatePaths.h"
namespace mobile {
// Matches desktop/sound-bank.cjs: twelve uniquely named notes, 60 s pads, 10 s clicks.
inline int padFileNote(const juce::String& filename){static const std::regex expression("(^|[\\s_-])([A-G](?:#|b|s)?)(?=$|[\\s_-])",std::regex::icase);std::smatch match;auto name=juce::File(filename).getFileNameWithoutExtension().toStdString();if(!std::regex_search(name,match,expression))return -1;auto key=juce::String(match[2].str()).replace("s","#",true);return note(key);}
inline juce::var soundBankState(const juce::File& root){auto state=juce::JSON::parse(root.getChildFile("sound-bank.json").loadFileAsString());if(!state.isObject())state=juce::var(new juce::DynamicObject());return state;}
inline juce::File bankFile(const juce::File& root,const juce::var& state,const char* kind,int index=0){auto pads=state["pads"];if(juce::String(kind)=="pads"&&(!pads.isArray()||index<0||index>=pads.size()))return {};auto path=juce::String(kind)=="pads"?pads[index].toString():state[kind].toString();if(path.isEmpty())return {};juce::File file=privateFile(root,path);return file.isAChildOf(root.getChildFile("Sounds"))&&file.existsAsFile()?file:juce::File();}
inline juce::var importSoundBank(const juce::File& root,const juce::String& kind,const juce::Array<juce::File>& files){bool pads=kind=="pads";if((!pads&&kind!="normal"&&kind!="accent")||files.size()!=(pads?12:1))throw ImportError(ImportError::invalid);juce::Array<int> indexes;juce::AudioFormatManager formats;formats.registerBasicFormats();for(auto& file:files){int index=pads?padFileNote(file.getFileName()):0;if(index<0||indexes.contains(index))throw ImportError(ImportError::ambiguous);indexes.add(index);std::unique_ptr<juce::AudioFormatReader> reader(formats.createReaderFor(file));if(!reader||reader->numChannels<1||reader->numChannels>2||reader->lengthInSamples<=0||reader->sampleRate<=0||reader->lengthInSamples/reader->sampleRate>(pads?60.1:10.))throw ImportError(ImportError::unsupported);}
    auto directory=root.getChildFile("Sounds").getChildFile(pads?"Pads":"Click").getChildFile(juce::Uuid().toString());if(directory.createDirectory().failed())throw ImportError(ImportError::access);auto state=soundBankState(root);juce::Array<juce::var> paths;for(int i=0;i<files.size();++i)paths.add(juce::var());try{for(int i=0;i<files.size();++i){auto target=directory.getChildFile((pads?flatKey(indexes[i]):kind)+files[i].getFileExtension().toLowerCase());if(!files[i].copyFileTo(target))throw ImportError(ImportError::access);paths.set(indexes[i],privateReference(root,target));}state.getDynamicObject()->setProperty(juce::Identifier(kind),pads?juce::var(paths):paths[0]);if(!root.getChildFile("sound-bank.json").replaceWithText(juce::JSON::toString(state)))throw ImportError(ImportError::access);return state;}catch(...){directory.deleteRecursively();throw;}
}
}
